(272, '2023-02-16 14:22:51', 67, '{\"text\":\"<h3>Můj e-shop<\\/h3>\\r\\n\\r\\n<p>Móda, sport, obuv, doplňky, nejnovější kousky ze světa módy na jednom místě. Stylové oblečení pro každého z vás. Vybírejte z nejnovějších kolekcí. Nenechte si uniknout žádné slevy a výprodeje. Rychlé dodání, bezpečné platby.<\\/p>\\r\\n\",\"image\":\"1c030fc367e1b0e5.png\"}', 15, 1, 1),
(273, '2023-02-16 14:22:51', 67, '{\"title\":\"Jdeme poctivě za svým cílem\",\"perex\":\"Máme snahu, aby naše doplňky, které vzejdou z laboratoří, mohli využívat všichni profesionální sportovci, ale i široká veřejnost.\",\"text\":\"<p>Naše heslo je <strong>NO DOPING<\\/strong>, čehož se přísně držíme! Snažíme se o co největší efektivitu a účinnost našich produktů, ale vše bez zakázaných látek. Naše produkty jsou <strong>CERTIFIKOVANÉ<\\/strong>! Věříme, že toto je ta správná cesta. Bez obav z dopingových kontrol, bez obav o své vlastní zdraví. S vědomím, že tělu dodáváme vše potřebné od <strong>posílení imunity<\\/strong>, až po <strong>zlepšení výkonnosti, vytrvalosti<\\/strong> atd.&nbsp; Máme rádi pod kontrolou, co do svého těla doplňujeme a nyní jsme teprve spokojení.<\\/p>\\r\\n\\r\\n<p>Těšíme se na Vaše recenze a až budeme dostávat zpětnou vazbu. Jak jste spokojeni a jak se zlepšují vaše sportovní výkony. Osobně jsme o lepších výsledcích přesvědčeni na vlastní kůži.&nbsp;<\\/p>\\r\\n\\r\\n<p>Hodně štěstí a úspěchů ve sportu a zdravém životním stylu přeje společnost The&nbsp;Good Choice - Ta správná volba!<\\/p>\\r\\n\",\"buttons\":{\"1\":{\"button_text\":\"Nabídka produktů\",\"button_link\":\"\\/cs\\/produkty\"}},\"image\":\"82421f6f5b6064cc.jpg\",\"image_pos\":\"left\",\"text_size\":\"standard\",\"data\":\"{\\\"title\\\":\\\"Síla je stav mysli\\\",\\\"perex\\\":\\\"Trendy obuv pro všechna roční období i příležitosti.\\\",\\\"text\\\":\\\"<p>Móda, sport, obuv, doplňky, nejnovější kousky ze světa módy na jednom místě. Stylové oblečení pro každého z vás. Vybírejte z nejnovějších kolekcí. Nenechte si uniknout žádné slevy a výprodeje. Rychlé dodání, bezpečné platby.<\\\\\\/p>\\\\r\\\\n\\\",\\\"buttons\\\":[],\\\"image\\\":\\\"1a4c69c285f8e409.png\\\",\\\"image_pos\\\":\\\"left\\\",\\\"text_size\\\":\\\"standard\\\",\\\"data\\\":\\\"{\\\\\\\"title\\\\\\\":\\\\\\\"Síla je stav mysli\\\\\\\",\\\\\\\"perex\\\\\\\":\\\\\\\"Trendy obuv pro všechna roční období i příležitosti.\\\\\\\",\\\\\\\"text\\\\\\\":\\\\\\\"<p>Móda, sport, obuv, doplňky, nejnovější kousky ze světa módy na jednom místě. Stylové oblečení pro každého z vás. Vybírejte z nejnovějších kolekcí. Nenechte si uniknout žádné slevy a výprodeje. Rychlé dodání, bezpečné platby.<\\\\\\\\\\\\\\/p>\\\\\\\\r\\\\\\\\n\\\\\\\",\\\\\\\"buttons\\\\\\\":{\\\\\\\"1\\\\\\\":{\\\\\\\"button_text\\\\\\\":\\\\\\\"Více o společnosti\\\\\\\",\\\\\\\"button_link\\\\\\\":\\\\\\\"\\\\\\\\\\\\\\/cs\\\\\\\\\\\\\\/o-nas\\\\\\\"}},\\\\\\\"image\\\\\\\":\\\\\\\"1a4c69c285f8e409.png\\\\\\\",\\\\\\\"image_pos\\\\\\\":\\\\\\\"left\\\\\\\",\\\\\\\"text_size\\\\\\\":\\\\\\\"standard\\\\\\\"}\\\",\\\"pos_order\\\":1.5}\",\"pos_order\":1.5,\"background_color\":\"standard\"}', 1, 2, 1),
