(327, '2023-02-16 14:22:51', 92, '{\"files\":\"{\\\"file\\\":\\\"23bd3fc8f3723774.jpg\\\",\\\"name\\\":\\\"Výpis z OR\\\",\\\"extension\\\":\\\"jpg\\\",\\\"formattedFileSize\\\":\\\"209.22 KB\\\"}; {\\\"file\\\":\\\"03084a393bc8d5f9.png\\\",\\\"name\\\":\\\"Výroční zpráva 2021\\\",\\\"extension\\\":\\\"png\\\",\\\"formattedFileSize\\\":\\\"244.27 KB\\\"}; {\\\"file\\\":\\\"78347e4d87a79f47.jpg\\\",\\\"name\\\":\\\"Výroční zpráva 2020\\\",\\\"extension\\\":\\\"jpg\\\",\\\"formattedFileSize\\\":\\\"159.04 KB\\\"}; {\\\"file\\\":\\\"3ff793834ea23897.jpg\\\",\\\"name\\\":\\\"Výroční zpráva 2019\\\",\\\"extension\\\":\\\"jpg\\\",\\\"formattedFileSize\\\":\\\"174.61 KB\\\"}\",\"title\":\"Soubory ke stažení\",\"data\":\"{\\\"files\\\":\\\"{\\\\\\\"file\\\\\\\":\\\\\\\"23bd3fc8f3723774.jpg\\\\\\\",\\\\\\\"name\\\\\\\":\\\\\\\"1647935782_89d6726.jpg\\\\\\\"}; {\\\\\\\"file\\\\\\\":\\\\\\\"03084a393bc8d5f9.png\\\\\\\",\\\\\\\"name\\\\\\\":\\\\\\\"1647935781_fd7145e.png\\\\\\\"}; {\\\\\\\"file\\\\\\\":\\\\\\\"78347e4d87a79f47.jpg\\\\\\\",\\\\\\\"name\\\\\\\":\\\\\\\"1647935781_b862d21.jpg\\\\\\\"}; {\\\\\\\"file\\\\\\\":\\\\\\\"3ff793834ea23897.jpg\\\\\\\",\\\\\\\"name\\\\\\\":\\\\\\\"1647935781_0bef7e4.jpg\\\\\\\"}\\\",\\\"title\\\":\\\"Soubory ke stažení\\\"}\",\"text\":\"\",\"buttons\":[]}', 18, 7, 1),
