INSERT INTO `email_templates_mld` (`email_templates_id`, `languages_id`, `name`, `subject`, `email_from`, `email_to`, `text`) VALUES
(7, 'cs', 'Newsletter – žádost o potvrzení', 'Potvrzení odběru newsletteru', 'robot@pro-idea.cz', '', '<p>Hezký den,</p>\n\n<p>potvrďte prosím odběr novinek kliknutím na odkaz:<br />\n<a href=\"{*URL*}\">{*URL*}</a></p>\n\n<p><br />\nTým e-shopu</p>\n'),
(8, 'cs', 'Kontaktní formulář', 'Nová zpráva', 'info@pro-idea.cz', 'info@pro-idea.cz', '<p>Hezký den,</p>\n\n<p>přišla nová zpráva:</p>\n\n<p>Jméno: {*NAME*}<br />\nE-mail: {*EMAIL*}<br />\nTelefon: {*PHONE*}</p>\n\n<p>Text:<br />\n{*TEXT*}</p>\n\n<p><br />\nTým e-shopu</p>\n');
