INSERT INTO `faq_mld` (`faq_id`, `languages_id`, `is_active`, `is_active_from`, `is_active_to`, `name`, `text`) VALUES
(6, 'cs', 1, NULL, NULL, 'Lze objednávku dodatečně upravit?', '<p>Ano, kdykoliv než dojde k předání zásilky smluvnímu přepravci.</p>\n'),
(7, 'cs', 1, NULL, NULL, 'Zboží mi nevyhovuje. Co mám dělat?', '<p>Zboží nám můžete vrátit, nebo vyměnit za jiné dle našich obchodních podmínek. Máte na to 14 dnů od obdržení zásilky.</p>\n'),
(8, 'cs', 1, NULL, NULL, 'Za jak dlouho objednané zboží odešleme?', '<p>Zboží, které je v našem e-shopu skladem, odesíláme do 24-48 hod. po objednání.</p>\n');
